  "root_cause": {
    "category": "deploy_regression",
    "service": "shipping",
    "summary": "Shipping began returning internal errors immediately after a deployment, causing downstream failures."
  },
  "confidence": "high",
  "causal_chain": [
    {
      "claim": "A deployment of the shipping service started at +60.028s and finished at +64.028s.",
      "status": "confirmed",
      "cites": ["ops-E0001", "ops-E0002"]
    },
    {
      "claim": "After the deployment, shipping logged a service started event for version v1.3.9 at +64.028s.",
      "status": "confirmed",
      "cites": ["shipping-L0003f"]
    },
    {
      "claim": "Shipping began returning internal_error responses, as shown by a span at +64.153s with status 500 and error internal_error.",
      "status": "confirmed",
      "cites": ["shipping-S004b9"]
    },
    {
      "claim": "Broker detected these as upstream errors (dependency shipping returned 500) and scheduled retries with a 100ms backoff.",
      "status": "confirmed",
      "cites": ["broker-L00047", "broker-L00048"]
    },
    {
      "claim": "Due to repeated failures in broker→shipping calls, broker returned errors to ingest, which propagated to the api.",
      "status": "uncertain",
      "cites": []
    },
    {
      "claim": "The api observed 500 internal_error responses to users at the start of the sustained burst (+62.790s).",
      "status": "confirmed",
      "cites": ["api-S00932"]
    }
  ],
  "alternatives": [
    {
      "category": "dependency_slow",
      "service": "broker",
      "why_less_likely": "Broker latency spikes occurred early in the trace (+10‑+33 s) and were not sustained; the sustained failures coincided with broker reporting upstream errors from shipping, not its own slowness.",
      "cites": ["broker-S00366", "broker-S00893", "broker-S009be"]
    },
    {
      "category": "internal_errors",
      "service": "shipping",
      "why_less_likely": "While shipping does return internal errors, the timing shows these errors began only after the shipping deploy; without the deploy there is no explanation for the sudden surge, making the deploy regression a more precise cause.",
      "cites": ["shipping-S0030b", "shipping-S003e6"]
    }
  ]
}
